def compute(vars):
    debt_target = vars["v1"]
    other_target = vars["v2"]
    difference = debt_target - other_target
    return {
        "value": difference,
        "trace": {
            "debt_target": debt_target,
            "other_target": other_target,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
